cat > /tmp/fix.mjs <<'EOF'
import fs from "fs";
import {execSync} from "child_process";
let out="";
try{execSync("npx ngc -p tsconfig.json 2>&1",{encoding:"utf8",maxBuffer:1e8})}catch(e){out=e.stdout}
out=out.replace(/\x1b\[[0-9;]*m/g,"");
const m=[...out.matchAll(/^(src[^:]*):(\d+):(\d+) - error NG8002: Can't bind to 'disableTooltip'/gm)];
const by={};
for(const x of m)(by[x[1]]??=[]).push([+x[2],+x[3]]);
for(const [f,ps] of Object.entries(by)){
 const L=fs.readFileSync(f,"utf8").split("\n");
 for(const [l,c] of ps.sort((a,b)=>b[0]-a[0]||b[1]-a[1])){
  L[l-1]=L[l-1].slice(0,c-1)+L[l-1].slice(c-1).replace("disableTooltip","hideHint");
 }
 fs.writeFileSync(f,L.join("\n"));
}
console.log(m.length);
EOF
cp /tmp/fix.mjs ./_fix.mjs; for i in 1 2 3; do node _fix.mjs; done; rm _fix.mjs
npx ngc -p tsconfig.json 2>&1 | sed 's/\x1b\[[0-9;]*m//g' | grep -E "error" | head

