cat > _p.mjs <<'EOF'
import fs from "fs";
import {execSync} from "child_process";
const files=execSync("git ls-files src",{encoding:"utf8"}).split("\n").filter(f=>/\.(html|ts)$/.test(f));
const re=/<app-(?:pill|fancy-pill|status-pill)\b(?:"[^"]*"|'[^']*'|[^>"'])*>/g;
let n=0;
for(const f of files){
 const s=fs.readFileSync(f,"utf8");
 const t=s.replace(re,tag=>tag.replace(/(\s)disableTooltip(?=[\s>\/])/g,(m,a)=>{n++;return a+"hideHint"}));
 if(t!==s)fs.writeFileSync(f,t);
}
console.log(n);
EOF
node _p.mjs; rm _p.mjs
grep -rnE "disableTooltip" src | grep -vE "<app-card|\[disableTooltip\]=\"|pill-legacy" | head -40
npx ngc -p tsconfig.json 2>&1 | grep -c error

